document.function:
{ def caseObj ->
    // Na single-tenant Netgrif Platforme premenna workspace neexistuje a
    // processIdentifier je bez prefixu. Odvodime ho z vlastneho casu - funguje
    // rovnako na single-tenante (prazdny prefix) aj na multi-tenant eTasku.
    def pid = caseObj.processIdentifier
    return pid.contains("/") ? pid.substring(0, pid.lastIndexOf("/") + 1) : ""
}

{ def caseObj ->
    // Casov ai_config moze byt viac. Uprednostni ten s naplnenym ciselnikom,
    // inak by sme citali prazdny a ponuka modelov by bola prazdna.
    def cases = findCases { it.processIdentifier.eq(net_prefix(caseObj) + "ai_config") }
    if (!cases) return null
    def filled = cases.findAll { c -> ((c.dataSet["models_json"]?.value ?: "[]") as String).trim() != "[]" }
    return filled ? filled[0] : cases[0]
}

{ def key ->
    // Mongo nepovoluje bodku ani dolar v kluci mapy - options preto nesu slug.
    return (key as String).replace(".", "__D__").replace('$', "__S__")
}

{ def caseObj ->
    def cfg = find_ai_config(caseObj)
    def raw = cfg ? cfg.dataSet["models_json"]?.value : null
    return raw ? new groovy.json.JsonSlurper().parseText(raw as String) : []
}

{ origin, model, model_label, model_key, model_provider, models_status ->
    def cases = findCases { it.processIdentifier.eq(net_prefix(useCase) + "ai_config") }
    def cfg = find_ai_config(useCase)
    def list = read_models(useCase)
    def sel = list.findAll { m -> m.origin == origin.value }
    change model options {
        sel.collectEntries { m -> [(model_slug(m.key)): (m.provider ? (m.label + "  [" + m.provider + "]") : m.label) as String] }
    }

    if (!cases) {
        change models_status value { "Nenasiel sa ziadny case AI konfiguracia - vytvor ho a naplni ciselnik" }
    } else if (!cfg || !list) {
        change models_status value { "Ciselnik je prazdny (najdenych casov ai_config: " + cases.size() + ")" }
    } else {
        change models_status value { "Modely pre " + origin.value + ": " + sel.size() + " z " + list.size() +
                                     " (zdroj " + cfg.stringId + ", casov ai_config: " + cases.size() + ")" }
    }

    def hit = model.value ? sel.find { m -> model_slug(m.key) == model.value } : null
    if (model.value && !hit) {
        change model value { "" }
        change model_label value { "" }
        change model_key value { "" }
        change model_provider value { "" }
    } else if (hit) {
        change model_label value { hit.label }
        change model_key value { hit.key }
        change model_provider value { hit.provider ?: "" }
    }
}

{ updated_at, updated_by ->
    change updated_at value { java.time.LocalDateTime.now() }
    change updated_by value { userService.loggedOrSystem.email }
    def cfg = find_ai_config(useCase)
    if (cfg) {
        setData("t_config", cfg, ["stale_signal": ["value": useCase.stringId, "type": "text"]])
    }
}

actions.action:
show_audit: f.show_audit, model_provider: f.model_provider, updated_at: f.updated_at, updated_by: f.updated_by, models_status: f.models_status, model_label: f.model_label, model_key: f.model_key;
// Auditne polia su diagnostika, nie vstup - drzime ich zbalene, kym si ich niekto nevyziada.
boolean showIt = show_audit.value == true
make model_provider, visible on transitions when { showIt }
make model_provider, hidden on transitions when { !showIt }
make updated_at, visible on transitions when { showIt }
make updated_at, hidden on transitions when { !showIt }
make updated_by, visible on transitions when { showIt }
make updated_by, hidden on transitions when { !showIt }
make models_status, visible on transitions when { showIt }
make models_status, hidden on transitions when { !showIt }
make model_label, visible on transitions when { showIt }
make model_label, hidden on transitions when { !showIt }
make model_key, visible on transitions when { showIt }
make model_key, hidden on transitions when { !showIt }

origin: f.origin, model: f.model, model_label: f.model_label, model_key: f.model_key,
model_provider: f.model_provider, models_status: f.models_status;
load_models(origin, model, model_label, model_key, model_provider, models_status)

model: f.model, model_label: f.model_label, model_key: f.model_key,
model_provider: f.model_provider, updated_at: f.updated_at, updated_by: f.updated_by;

if (model.value) {
    def entry = read_models(useCase).find { m -> model_slug(m.key) == model.value }
    change model_label value { entry ? entry.label : "" }
    change model_key value { entry ? entry.key : "" }
    change model_provider value { entry ? (entry.provider ?: "") : "" }
    mark_updated(updated_at, updated_by)
}

origin: f.origin, model: f.model, model_label: f.model_label, model_key: f.model_key,
model_provider: f.model_provider, models_status: f.models_status;
load_models(origin, model, model_label, model_key, model_provider, models_status)

